/* A quieter entry and a continuous workshop-to-independent-learning journey. */
(()=>{
 const C=window.REILearningPathCore;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const read=()=>window.REILearningStore.readPath();
 const link=(href,text,cls='path-link')=>`<a class="${cls}" href="${href}">${text}<span aria-hidden="true">↗</span></a>`;
 function tabs(current){return `<nav class="path-tabs" aria-label="Learning workspace">${[['#learn','Learning library','learn'],['#practice','Practice lab','practice'],['#workbook','My workbook','workbook']].map(([href,label,key])=>`<a href="${href}" ${key===current?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`}
 function shell(body,current='learn'){return `<div class="path-page" data-learning-surface><a class="path-back path-home-link" href="#home">← REI homepage</a>${tabs(current)}${body}<footer class="path-help"><p>Your workbook saves in this browser. No account or automatic sharing.</p><div>${link('#backup','Back up or restore')}${link('#learning-evidence','How the learning activities were designed')}${link('#home','REI homepage')}</div></footer></div>`}
 function landing(){return `<div class="path-page path-landing" data-learning-surface><section class="path-welcome"><div><h1>Learn to ask.<br>Build the <em>evidence.</em></h1><p class="path-intro">A research space for curious students. Turn workshop ideas—or a question of your own—into something you can investigate.</p><p>Inside REI, learn from short worked examples, try research challenges and use practical tools to move your project forward.</p><div class="path-actions path-welcome-action">${link('#home','Enter REI','path-button')}</div><p class="path-muted">Short learning challenges, practical tools and your saved projects are inside.</p></div><div class="path-identity"><div class="sculpture" data-sculpture="38" aria-hidden="true"><img class="sculpture-fallback" src="particle-fallback.svg" alt=""><canvas></canvas></div><p>Question → sources → connections → research blueprint</p></div></section><footer class="path-help"><p>Free to use. Saved on this device. No account required.</p></footer></div>`}

 function rows(s,current=-1){return `<ol class="path-outline">${C.steps.map((step,i)=>{const count=step.fields.filter(([k])=>s.fields[k]?.trim()).length;return `<li><a href="#learn/${i}" ${i===current?'aria-current="step"':''}><span class="path-number">${String(i+1).padStart(2,'0')}</span><span><strong>${step.short}</strong><small>${count?count+' of '+step.fields.length+' prompts have notes':'No notes yet'}</small></span><span aria-hidden="true">→</span></a></li>`}).join('')}</ol>`}
 function dashboard(){const s=read(),has=Object.values(s.fields).some(x=>x.trim()),index=has?s.last:0;return shell(`<section class="path-heading"><h1>One research idea.<br><em>Six manageable steps.</em></h1><p>Start with an observation, not a finished topic. Follow the workshop sequence at your own pace. Your responses and practice revisions stay together in My workbook.</p>${link('#learn/'+index,has?'Continue step '+(index+1):'Begin step 1','path-button')}<p class="path-muted">${has?'Return to: '+esc(C.steps[index].short)+'.':'No seminar attendance is required.'}</p></section><section class="path-learning-routine"><h2>Your routine at each step</h2><ol><li><strong>Understand.</strong> Read the idea and open the example if you need it.</li><li><strong>Write.</strong> Apply the prompts to your own question.</li><li><strong>Practice.</strong> Try the suggested exercise, compare and revise.</li><li><strong>Continue.</strong> Follow the next-step link. Return whenever you need to.</li></ol><p>Your notes save in this browser. Recording an answer does not mean it has been assessed or approved.</p></section><details class="path-more"><summary>See all six steps or revisit one</summary>${rows(s)}</details><details class="path-more"><summary>Additional learning resources</summary><p>These are optional. The guided steps recommend relevant help as you go.</p><div>${link('#academy','Detailed lessons')}${link('#toolkit','Templates and checklists')}${link('#seminars','Additional workshops')}</div></details>`)}

 function stepView(i){if(!Number.isInteger(i)||!C.steps[i])return dashboard();const step=C.steps[i],s=read();return shell(`<div class="path-step-layout"><aside class="path-rail"><p class="path-current-step">Step ${i+1} of 6</p><details class="path-step-selector"><summary>View or change learning step</summary>${rows(s,i)}</details></aside><article class="path-step"><nav class="path-breadcrumb" aria-label="You are here"><a href="#learn">Learning path</a><span>Step ${i+1} of 6</span></nav><p class="path-origin">${esc(step.seminar)}</p><h1>${esc(step.title)}</h1><p class="path-intro">${esc(step.intro)}</p><div class="path-memory"><strong>Keep this in mind</strong><p>${esc(step.remember)}</p></div><ul class="path-concepts">${step.concepts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><details class="path-example"><summary>See a worked example</summary><p>${esc(step.example)}</p><p>Illustration only. Check evidence and requirements for your own discipline.</p></details><section class="path-writing"><h2>Make it yours</h2><p>Use your own idea or your seminar notes. You can leave a prompt and return to it later.</p><form data-path-form="${i}">${step.fields.map(([k,label,hint])=>`<label for="path-${k}">${esc(label)}<small id="help-${k}">${esc(hint)}</small><textarea id="path-${k}" name="${k}" rows="4" maxlength="3000" aria-label="${esc(label)}" aria-describedby="help-${k}">${esc(s.fields[k]||'')}</textarea></label>`).join('')}<p class="path-save" role="status" data-path-status>Notes save as you write on this device.</p><button type="submit" class="path-button">Save these notes</button></form></section><section class="path-extension"><h2>Next: practice this idea.</h2><p>Try the matching exercise, compare your reasoning and revise. The activity will point you to the next learning step.</p>${link('#practice/'+step.practice,C.activities.find(a=>a.id===step.practice).title,'path-button')}<details><summary>More help and research tools</summary>${step.links.map(([lesson,title])=>link('#lesson/'+lesson,esc(title))).join('')}${link(step.tool[0],step.tool[1])}<p>Project tools keep separate records. Nothing from this workbook is inserted into a proposal automatically.</p></details></section><nav class="path-step-actions" aria-label="Continue learning">${i?link('#learn/'+(i-1),'← Previous step'):link('#learn','Learning home')}${link(i===5?'#workbook':'#learn/'+(i+1),i===5?'Review my workbook':'Continue without practice: '+esc(C.steps[i+1].short),'path-link')}</nav></article></div>`)}
 function practiceHome(){const s=read(),groups=[['Shape and investigate','Start with a workable question and investigate the information you find.',['recall','question','verify']],['Connect and justify','Compare evidence, limit your claims and choose a method that fits.',['gap','claim','alignment']],['Review and revisit','Use feedback and another attempt to improve your reasoning.',['review','revisit']]];return shell(`<section class="path-heading"><h1>Practice one skill.<br><em>Then use it.</em></h1><p>The guided learning path recommends an activity at each step. Use this library for extra practice: choose a category, try an explanation, compare it with guidance and revise.</p></section>${groups.map(([title,description,ids],groupIndex)=>`<section class="path-practice-group"><h2>${groupIndex+1}. ${title}</h2><p>${description}</p><ol class="path-activity-list">${ids.map(id=>{const a=C.activities.find(x=>x.id===id),r=s.practice[id];return `<li><span class="path-number" aria-hidden="true">${String(C.activities.indexOf(a)+1).padStart(2,'0')}</span><div><h3>${link('#practice/'+a.id,esc(a.title))}</h3><p>${r?.revision?.trim()?'Your revision is saved. Revisit it or try again.':r?.attempt?.trim()?'Your first attempt is saved.':'Try → compare → revise.'}</p></div></li>`}).join('')}</ol></section>`).join('')}<details class="path-more"><summary>How the activities were designed</summary><p>These are fictional exercises and do not automatically assess your study. A saved response is not a grade or a measure of mastery.</p>${link('#learning-evidence','Read the research and its limits')}</details>`,'practice')}

 function comparison(a,r){return `${a.options?`<p class="path-feedback">${esc(a.feedback[r.choice]||'Compare each option against the evidence.')}</p>`:''}<h2>A comparison answer</h2><p>${esc(a.model)}</p><h3>Transfer it to your research</h3><p>${esc(a.transfer)}</p><label for="practice-revision">Your revision and why it is stronger<textarea id="practice-revision" name="revision" rows="6" maxlength="3000">${esc(r.revision||'')}</textarea></label><button class="path-button" type="button" data-path-reviewed="${a.id}">Save revision and record this visit</button><p class="path-muted">${r.reviewed?'Last review recorded '+esc(new Date(r.reviewed).toLocaleDateString())+'. ':''}A recorded visit is not evidence of mastery.</p>`}
 function activityView(id){const a=C.activities.find(x=>x.id===id);if(!a)return practiceHome();const r=read().practice[id]||{},stepIndex=C.steps.findIndex(step=>step.practice===id);return shell(`<article class="path-activity"><a class="path-back" href="#practice">← Practice lab</a><p class="path-origin">${esc(a.kind)}</p><h1>${esc(a.title)}</h1><p class="path-intro">${esc(a.prompt)}</p><form data-practice-form="${a.id}">${a.options?`<fieldset><legend>Choose a starting interpretation</legend>${a.options.map((x,i)=>`<label class="path-option"><input type="radio" name="choice" value="${i}" ${r.choice===i?'checked':''}>${esc(x)}</label>`).join('')}</fieldset>`:''}<label for="practice-attempt">Your first explanation<textarea id="practice-attempt" name="attempt" rows="6" maxlength="3000" placeholder="Try your reasoning before opening the comparison answer.">${esc(r.attempt||'')}</textarea></label><p role="status" class="path-save" data-path-status>Notes save as you write on this device.</p><button type="submit" class="path-button">${r.revealed?'Compare my reasoning again':'Compare my reasoning'}</button><section id="path-comparison" class="path-comparison" ${r.revealed?'':'hidden'}>${r.revealed?comparison(a,r):''}</section></form><details class="path-evidence-note"><summary>Why this kind of practice?</summary><p>This is REI’s adaptation of the following research, not an exercise tested in those studies.</p>${a.evidence.map(id=>{const x=C.sources.find(s=>s.id===id);return `<p><a href="${x.url}" target="_blank" rel="noopener noreferrer">${esc(x.citation)}</a>: ${esc(x.use)} ${esc(x.limit)}</p>`}).join('')}</details><div class="path-step-actions">${stepIndex>=0?link(stepIndex===5?'#workbook':'#learn/'+(stepIndex+1),stepIndex===5?'Next: review my workbook':'Next: '+esc(C.steps[stepIndex+1].short),'path-button'):link('#workbook','Review my workbook','path-button')}<details><summary>Revisit or choose another activity</summary>${stepIndex>=0?link('#learn/'+stepIndex,'Return to this learning step'):''}${link('#practice','Practice library')}</details></div></article>`,'practice')}
 function workbook(){const s=read();return shell(`<section class="path-heading"><h1>Your thinking.<br><em>In one place.</em></h1><p>Your learning notes form a preliminary research blueprint. Keep revising it and check the reasoning with a supervisor.</p><div class="path-actions"><button class="path-button" type="button" data-path-export>Download readable workbook</button>${link('#backup','Back up the editable workbook')}</div><p role="status" data-export-status class="path-muted">Readable downloads are Markdown. A workspace JSON backup preserves editable notes and practice.</p></section><div class="path-workbook">${C.steps.map((step,i)=>`<section><div class="path-section-title"><h2>${esc(step.short)}</h2><a href="#learn/${i}">Edit step ${i+1} ↗</a></div><dl>${step.fields.map(([k,label])=>`<dt>${esc(label)}</dt><dd class="${s.fields[k]?.trim()?'':'path-missing'}">${s.fields[k]?.trim()?esc(s.fields[k]):'Not recorded yet — return to this step when ready.'}</dd>`).join('')}</dl></section>`).join('')}<section><h2>Your practice and revisions</h2>${C.activities.filter(a=>s.practice[a.id]?.attempt).map(a=>`<details><summary>${esc(a.title)}</summary><h3>First attempt</h3>${a.options&&Number.isInteger(s.practice[a.id].choice)?`<p>Chosen interpretation: ${esc(a.options[s.practice[a.id].choice])}</p>`:''}<p>${esc(s.practice[a.id].attempt)}</p><h3>Revision</h3><p>${esc(s.practice[a.id].revision||'No revision recorded yet.')}</p>${link('#practice/'+a.id,'Revisit this activity')}</details>`).join('')||`<p>No practice attempts yet. ${link('#practice','Choose a practice activity')}</p>`}</section></div><section class="path-more"><h2>Ready to work with real sources?</h2><p>Create or open a research project for your source library, evidence, synthesis and proposal. This workbook stays separate so your project text is never overwritten.</p>${link('#research','Open research studio','path-button')}<p>Writing in the full lesson editors stays in your <a href="#notebook/draft">full lesson drafts</a>. It is separate from this guided workbook.</p><p>To request feedback, download your workbook and share it yourself through a channel you trust. REI sends no messages and issues no certificates.</p></section>`,'workbook')}
 function evidence(){return shell(`<section class="path-heading"><h1>A learning design<br>you can <em>inspect.</em></h1><p>The seminar proposal supplies the pathway. Published research informs how you practise. REI’s activities are adaptations; their educational impact has not yet been measured.</p></section><section class="path-evidence"><h2>What comes from the writeshop?</h2><p>The research mindset, ideas and questions, source search/evaluation, literature synthesis, a preliminary framework and blueprint, and reflection follow the supplied activity proposal. The original nine lessons and research tools deepen those stages.</p><h2>What informs the extra practice?</h2>${C.sources.map(x=>`<article><h3>${esc(x.title)}</h3><a href="${x.url}" target="_blank" rel="noopener noreferrer">${esc(x.citation)} ↗</a><p>${esc(x.finding)}</p><dl><dt>REI’s adaptation</dt><dd>${esc(x.use)}</dd><dt>Evidence boundary</dt><dd>${esc(x.limit)}</dd></dl></article>`).join('')}<h2>Why short examples and challenges?</h2><p>The new learning library presents a worked example before a short decision and explanation. <a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/1" target="_blank" rel="noopener noreferrer">The IES practice guide on organizing instruction</a> recommends alternating worked examples and problem solving. Applying that mechanism to REI’s research scenarios is an adaptation; these six lessons have not demonstrated learning gains. Planning tools use transparent templates, and the paper finder retrieves Crossref metadata rather than generating citations.</p><details class="library-support"><summary>Why goals, visual cues and a second situation?</summary><p>Lesson goals and labeled examples make the intended decision visible. Feedback stays beside the choice, and a different-context question creates another opportunity to apply the idea. These are REI adaptations, not a validated assessment or proof of transfer.</p><p><a href="https://doi.org/10.1017/9781108894333.022" target="_blank" rel="noopener noreferrer">Cambridge: signaling and cueing</a> · <a href="https://pubmed.ncbi.nlm.nih.gov/29733621/" target="_blank" rel="noopener noreferrer">Pan and Rickard: transfer review</a> · <a href="https://educationendowmentfoundation.org.uk/education-evidence/teaching-learning-toolkit/feedback" target="_blank" rel="noopener noreferrer">EEF: feedback guidance</a></p></details><h2>What still needs evaluation?</h2><p>Expert curriculum review, student usability tests and an appropriate learning evaluation are still needed. A filled workbook or correct scenario answer does not establish research readiness, ethical approval or mastery. Use disciplinary and institutional guidance.</p></section>`)}
 function save(s,message='Saved on this device.'){const ok=window.REILearningStore.writePath(s);C.steps.forEach((step,i)=>{const count=step.fields.filter(([k])=>s.fields[k]?.trim()).length;document.querySelectorAll('.path-outline a[href="#learn/'+i+'"] small').forEach(el=>el.textContent=count?count+' of '+step.fields.length+' prompts have notes'+(ok?'':' in this session'):'No notes yet')});document.querySelectorAll('[data-path-status]').forEach(el=>el.textContent=ok?message:'Not saved to browser storage. Your text is kept in this session. Retry saving or download a backup before leaving.');return ok}
 function capture(form){const s=read(),values=Object.fromEntries(new FormData(form));if(form.dataset.pathForm!==undefined){for(const [key] of C.steps[Number(form.dataset.pathForm)].fields)s.fields[key]=String(values[key]||'');s.last=Number(form.dataset.pathForm)}else{const id=form.dataset.practiceForm,r=s.practice[id]||{choice:null,reviewed:null,revealed:false};r.attempt=String(values.attempt||'');if('revision'in values)r.revision=String(values.revision||'');r.choice='choice'in values?Number(values.choice):null;s.practice[id]=r}return s}
 document.addEventListener('input',event=>{const form=event.target.closest('[data-path-form],[data-practice-form]');if(form)save(capture(form))});
 document.addEventListener('change',event=>{const form=event.target.closest('[data-practice-form]');if(form)save(capture(form))});
 document.addEventListener('submit',event=>{const form=event.target;if(!form.matches('[data-path-form],[data-practice-form]'))return;event.preventDefault();const s=capture(form);if(form.dataset.pathForm!==undefined){save(s);return}const a=C.activities.find(x=>x.id===form.dataset.practiceForm),r=s.practice[a.id];if(!r.attempt.trim()||(a.options&&r.choice===null)){form.querySelector('[data-path-status]').textContent='Write your explanation'+(a.options?' and choose an interpretation':'')+' before comparing.';return}r.revealed=true;save(s);const panel=form.querySelector('#path-comparison');panel.hidden=false;panel.innerHTML=comparison(a,r);panel.tabIndex=-1;panel.focus({preventScroll:true})});
 document.addEventListener('click',event=>{const exportButton=event.target.closest('[data-path-export]');if(exportButton){const url=URL.createObjectURL(new Blob([C.markdown(read())],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='rei-learning-workbook.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);document.querySelector('[data-export-status]').textContent='Workbook download requested. Check that your browser kept the file.'}const reviewed=event.target.closest('[data-path-reviewed]');if(reviewed){const form=reviewed.closest('form'),s=capture(form),r=s.practice[reviewed.dataset.pathReviewed];if(!r.revision?.trim()){form.querySelector('[data-path-status]').textContent='Write a revision and explain what changed before recording this visit.';return}r.reviewed=new Date().toISOString();save(s,'Revision saved and this visit recorded. Return later to try a fresh example.')}});
 function contextBar(){document.querySelector('#path-return')?.remove();const hash=location.hash;if(!/^#(lesson|resource|workshop)\//.test(hash))return;const bar=document.createElement('nav');bar.id='path-return';bar.className='path-return';bar.setAttribute('aria-label','Return to your learning');bar.innerHTML='<a href="#learn">← Learning path</a><a href="#practice">Practice lab</a><a href="#workbook">My workbook</a>';document.querySelector('#main').prepend(bar)}
 addEventListener('rrh:route',contextBar);
 window.REILearningPath={landing,dashboard,stepView,practiceHome,activityView,workbook,evidence};
})();
